<?php

namespace App\Modules\Website\Application;

use App\Modules\Website\Infrastructure\WebsitePage;
use Illuminate\Support\Facades\DB;

final class InformationPageService
{
    public function published(string $slug): array
    {
        $page = WebsitePage::query()->where('slug', $slug)->whereNotNull('published_snapshot')->first();
        return $page ? app(PageService::class)->render($page) : [];
    }

