        return [
            ['id' => 'collect', 'title' => 'اطلاعات موردنیاز نوبت‌دهی', 'icon' => 'file', 'summary' => 'اطلاعات پایه برای ثبت و پیگیری نوبت', 'text' => 'برای ورود و ثبت نوبت، شماره همراه رزروکننده، اطلاعات پایه بیمار، خدمت انتخاب‌شده، تاریخ و ساعت نوبت و وضعیت پرداخت در سامانه استفاده می‌شود. اطلاعات هر فرم مرتبط با خدمت، در همان فرم از مراجعه‌کننده دریافت می‌شود.'],
