    /** Public display of current settings, without exposing the full configuration row. */
    public function policies(): array
    {
        $settings = DB::table('booking_settings')->where('id', 1)->first(['hold_minutes', 'cutoff_hours']);
        $horizon = DB::table('schedule_state')->where('id', 1)->value('horizon_days');
        $hold = $settings?->hold_minutes;
        $cutoff = $settings?->cutoff_hours;
        return [
            ['id' => 'booking', 'title' => 'ثبت نوبت', 'icon' => 'calendar', 'summary' => $horizon !== null ? 'افق رزرو: '.(int) $horizon.' روز، با احتساب امروز' : 'زمان‌های قابل رزرو را در تقویم بررسی کنید.', 'text' => 'ثبت نوبت از تقویم آنلاین و با تأیید شماره همراه رزروکننده انجام می‌شود. زمان انتخاب‌شده هنگام ثبت، دوباره از نظر ظرفیت بررسی می‌شود.'],
            ['id' => 'payment', 'title' => 'پرداخت و رزرو موقت', 'icon' => 'wallet', 'summary' => $hold !== null ? 'مهلت رزرو موقت: '.(int) $hold.' دقیقه' : 'مهلت پرداخت در مرحله رزرو نمایش داده می‌شود.', 'text' => 'رزرو موقت با نوبت قطعی تفاوت دارد. وضعیت پرداخت و تأیید نهایی را در صفحه نوبت خود بررسی کنید. تکمیل‌نشدن پرداخت در مهلت رزرو موقت، می‌تواند ظرفیت را آزاد کند.'],
            ['id' => 'change', 'title' => 'تغییر زمان نوبت', 'icon' => 'clock', 'summary' => $cutoff !== null ? 'مهلت عادی تغییر: تا '.(int) $cutoff.' ساعت پیش از شروع' : 'مهلت تغییر مطابق تنظیمات فعال سامانه است.', 'text' => 'زمان جدید باید ظرفیت آزاد داشته باشد. در صورت ناموفق‌بودن تغییر زمان، نوبت قبلی حفظ می‌شود.'],
            ['id' => 'cancel', 'title' => 'لغو و اعتبار', 'icon' => 'file', 'summary' => $cutoff !== null ? 'مهلت عادی لغو: تا '.(int) $cutoff.' ساعت پیش از شروع' : 'مهلت لغو مطابق تنظیمات فعال سامانه است.', 'text' => 'لغو نوبت از صفحه پیگیری نوبت و با بررسی مجوز و مهلت آن انجام می‌شود. مبلغ قابل برگشت نوبت پرداخت‌شده، پس از لغو مجاز به اعتبار داخلی تبدیل می‌شود؛ درخواست استرداد از مسیر اعتبار و استرداد، نیازمند بررسی است.'],
        ];
    }
